def _trivial_tmpl(pointed_ketiv, unpointed_ketiv, pointed_qere, sug=None):
    elements = [
        ["מ:קו״כ-אם-2"],
        [pointed_ketiv],
        [unpointed_ketiv],
        [pointed_qere],
    ]
    if sug is not None:
        elements.append([f"סוג={sug}"])
    return wtp.mktmpl(elements)


def _std_kq_tmpl(pointed_ketiv, pointed_qere):
    return wtp.mktmpl([["כו״ק"], [pointed_ketiv], [pointed_qere]], ignore_equals=True)


def _special_kq_tmpl(sug_text):
    return wtp.mktmpl([["מ:כו״ק מיוחד"], ["כְּתִיב"], ["קרי"], [f"סוג={sug_text}"]])


